"""

"""
from threading import Thread
from time import sleep
try:
    from queue import Queue, Empty
except ImportError:
    from Queue import Queue, Empty
import logging

log = logging.getLogger("taf.gnb.oam.ne3s.ws.logger")


NOTIFICATION_WORKER = None
NOTIFICATION_WORKER_THREAD = None
NOTIFICATION_WORKER_THREAD_NAME = "NotificationsWorkerThread"


class WorkerNotStarted(Exception):
    pass


class Notifications(object):
    DEFAULT_QUEUE_MAX_SIZE = 10000
    DEFAULT_QUEUE_TIMEOUT = 1
    name = None
    worker = None
    _worker_thread = None
    _queue = None
    queue_timeout = None

    def __init__(self, name, filters, queue_timeout=DEFAULT_QUEUE_TIMEOUT, queue_size=DEFAULT_QUEUE_MAX_SIZE):
        self.name = name
        self.queue_timeout = queue_timeout
        self._setup_worker(filters=filters, queue_size=queue_size)

    def _setup_worker(self, filters, queue_size):
        if NOTIFICATION_WORKER is None:
            log.info("Creating new NotificationWorker")
            self._queue = Queue(maxsize=queue_size)
            self.worker = NotificationWorker(queue=self._queue, filters=filters)
            self._worker_thread = Thread(
                name=NOTIFICATION_WORKER_THREAD_NAME,
                target=self.worker.start_monitoring,
                args=(self.queue_timeout,))
            self._worker_thread.daemon = True
            self._worker_thread.start()

            self.set_worker_singleton_data()

        else:
            self.worker = NOTIFICATION_WORKER
            self._worker_thread = NOTIFICATION_WORKER_THREAD
            self._queue = self.worker.queue
            self.worker.reconfigure_filters(filters=filters)

    def set_worker_singleton_data(self):
        global NOTIFICATION_WORKER_THREAD
        NOTIFICATION_WORKER_THREAD = self._worker_thread

        global NOTIFICATION_WORKER
        NOTIFICATION_WORKER = self.worker

    def get_message(self, stream, timeout=5):
        return self.worker.get_message(filter_name=self.name, stream_name=stream, timeout=timeout)

    def get_queue(self):
        return self._queue

    def update_filters(self, new_filters):
        self.worker.reconfigure_filters(filters=new_filters)

    def disable(self):
        self.worker.remove_filter(filter_name=self.name)

    def add_streams(self, streams, overwrite=False):
        self.worker.add_streams(filter_name=self.name, streams=streams, overwrite=overwrite)

    def remove_streams(self, streams):
        self.worker.remove_streams(filter_name=self.name, streams=streams)


class NotificationWorker(object):
    DEFAULT_MONITORING_INTERVAL = 0.01
    GRACEFUL_SHUTDOWN_GRACE_PERIOD = 1
    filters = None
    stopped = False
    paused = False
    queue = None

    def __init__(self, queue, filters):
        """

        :param SimpleQueue queue:
        :param List[MessageFilter] filters:
        """
        self.queue = queue
        self.filters = {}

        for msg_filter in filters:
            self.filters[msg_filter.name] = msg_filter

    def start_monitoring(self, timeout, monitoring_interval=DEFAULT_MONITORING_INTERVAL):  # noqa: C901
        while self.stopped is False:
            try:

                sleep(monitoring_interval)

                if self.paused:
                    continue

                message = self.queue.get(timeout=timeout)
                log.info("Notification Worker received message: {}".format(message))
                if message.filter_name not in self.filters:
                    log.warn("Filter {} for message {} is not configured".format(message.filter_name, message))
                    continue

                self.filters.get(message.filter_name).put_message(message=message)
            except (Empty, EOFError):
                pass
            except Exception as e:
                log.warn("Unhandled exception occurred in NotificationWorker during message handling, Error: {}".format(e))
        else:
            log.info("NotificationsWorker {name} is now stopped".format(name=NOTIFICATION_WORKER_THREAD_NAME))

    def reconfigure_filters(self, filters):
        """
        Updates configuration for provided filters.
        Overwrites any existing streams.

        :param List[MessageFilter] filters:
        """
        log.info("Reconfiguring filters to add {}".format(filters))
        for msg_filter in filters:
            if msg_filter.name in self.filters:
                log.info("Updating existing filter {}".format(msg_filter.name))
                self.filters.get(msg_filter.name).update_streams(msg_streams=msg_filter.get_streams(), overwrite=True)
            else:
                log.info("Adding new filter {}".format(msg_filter.name))
                self.filters[msg_filter.name] = msg_filter

    def check_filter_is_known(self, filter_name):
        if filter_name not in self.filters:
            error_msg = "Filter name {} does not exist in known filters {}"
            raise ValueError(error_msg.format(filter_name, self.filters.keys()))

    def get_message(self, filter_name, stream_name, timeout):
        self.check_filter_is_known(filter_name)
        return self.filters.get(filter_name).get_message(stream_name=stream_name, timeout=timeout)

    def remove_filter(self, filter_name):
        self.check_filter_is_known(filter_name)
        self.filters.pop(filter_name)

    def add_streams(self, filter_name, streams, overwrite=False):
        self.check_filter_is_known(filter_name)
        self.filters.get(filter_name).update_streams(msg_streams=streams, overwrite=overwrite)

    def remove_streams(self, filter_name, streams):
        self.check_filter_is_known(filter_name)
        self.filters.get(filter_name).remove_streams(msg_streams=streams)

    def graceful_shutdown(self):
        self.stopped = True

    @staticmethod
    def is_running():
        if NOTIFICATION_WORKER is None or NOTIFICATION_WORKER_THREAD is None:
            return False
        return NOTIFICATION_WORKER_THREAD.is_alive()

    def stop_worker(self):
        """
        Graceful shutdown of threaded notification worker
        In case graceful wont work, after grace period a forceful thread termination shall be initiated.
        """
        self.graceful_shutdown()

        sleep(self.GRACEFUL_SHUTDOWN_GRACE_PERIOD)

        if self.is_running() is True:
            self.force_worker_shutdown()

        self.clear_worker_data()

    def force_worker_shutdown(self):
        NOTIFICATION_WORKER_THREAD.terminate()

    @staticmethod
    def clear_worker_data():
        global NOTIFICATION_WORKER
        global NOTIFICATION_WORKER_THREAD
        NOTIFICATION_WORKER = None
        NOTIFICATION_WORKER_THREAD = None


def get_notification_worker():
    return NOTIFICATION_WORKER


def get_notification_worker_thread():
    return NOTIFICATION_WORKER_THREAD
